 type Launcher struct{}
 func(r *Launcher) Launch(f func()){go f()}
 type P struct{permits Permit;other Permit;runner Launcher}
 func(p *P) Submit(f func()){
  select{case p.permits<-struct{}{}:p.runner.Launch(func(){p.execute(f)})}
 }
 func(p *P) execute(f func()){defer p.permits.giveBack();f()}
 func(l Permit) giveBack(){if l!=nil{<-l}}

